:root {
  --gold: #F6D43A;
  --dgold: #98831A;
  --black: #070707;
  --paper: #F4F2EC;
  --white: #FFFFFF;
  --serif: "Cormorant Garamond", serif;
  --sans: "Montserrat", sans-serif;
}
#stage { background: var(--black); color: var(--white); font-family: var(--sans); }
.bg { position: absolute; inset: 0; background: radial-gradient(120% 75% at 50% 42%, #171614 0%, #0b0b0a 55%, #050505 100%); }
.grain { position: absolute; inset: 0; opacity: 0.055; pointer-events: none; }
.scene { position: absolute; inset: 0; display: none; }

/* Type */
.line { position: absolute; left: 0; right: 0; text-align: center; white-space: nowrap; line-height: 1; }
.left { text-align: left; left: 90px; }
.serif { font-family: var(--serif); font-weight: 500; letter-spacing: -0.01em; }
.it { font-family: var(--serif); font-style: italic; font-weight: 600; color: var(--gold); }
.it.dark { color: var(--dgold); }
.label { font: 600 30px/1 var(--sans); letter-spacing: 0.32em; text-transform: uppercase; }
.m { display: inline-block; overflow: hidden; vertical-align: top; padding: 0.06em 0.1em 0.22em; margin: -0.06em -0.1em -0.22em; }
.mi { display: inline-block; }
.rule { position: absolute; height: 2px; background: var(--gold); transform-origin: 50% 50%; }

/* Devices */
.phone { position: absolute; transform-style: preserve-3d; }
.phone .back { position: absolute; inset: 0; border-radius: 80px; background: #1c1a15; transform: translateZ(-20px); box-shadow: 0 0 0 2px #2d2a22; }
.phone .body { position: absolute; inset: 0; border-radius: 80px; background: linear-gradient(150deg, #36332b 0%, #121212 28%, #0b0b0b 72%, #29261f 100%); box-shadow: inset 0 0 0 2px rgba(246,212,58,0.24), inset 0 0 0 11px #060606; }
.phone .screen { position: absolute; left: 14px; top: 14px; right: 14px; bottom: 14px; border-radius: 66px; overflow: hidden; background: #000; transform: translateZ(1px); }
.phone .screen img { position: absolute; left: 0; top: 0; width: 100%; height: 100%; object-fit: cover; object-position: 50% 0; }
.phone .island { position: absolute; left: 50%; top: 30px; width: 140px; height: 40px; margin-left: -70px; border-radius: 20px; background: #000; transform: translateZ(2px); }
.ground { position: absolute; border-radius: 50%; background: radial-gradient(closest-side, rgba(0,0,0,0.7), rgba(0,0,0,0)); }
.browser { position: absolute; border-radius: 22px; overflow: hidden; background: #111; box-shadow: 0 0 0 2px rgba(255,255,255,0.08); }
.browser .bar { height: 46px; background: #1b1b1b; display: flex; align-items: center; padding: 0 22px; gap: 11px; }
.browser .dot { width: 14px; height: 14px; border-radius: 50%; background: #3b3b3b; }
.browser .url { margin: 0 120px 0 40px; flex: 1; height: 26px; border-radius: 13px; background: #272727; }
.browser .screen { position: relative; width: 100%; height: calc(100% - 46px); overflow: hidden; }
.browser .screen img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 0; display: block; }
.floor { position: absolute; left: -660px; width: 2400px; height: 1700px; transform-origin: 50% 0; background-image: linear-gradient(rgba(255,255,255,0.08) 2px, transparent 2px), linear-gradient(90deg, rgba(255,255,255,0.08) 2px, transparent 2px); background-size: 120px 120px; -webkit-mask-image: radial-gradient(ellipse 50% 60% at 50% 0%, #000 0%, transparent 100%); mask-image: radial-gradient(ellipse 50% 60% at 50% 0%, #000 0%, transparent 100%); }

/* Method */
.paper { position: absolute; inset: 0; background: var(--paper); }
.track { position: absolute; width: 3px; background: var(--dgold); transform-origin: 50% 0; }
.node { position: absolute; width: 26px; height: 26px; margin: -13px 0 0 -13px; border-radius: 50%; background: var(--paper); border: 3px solid var(--dgold); }
.node i { position: absolute; inset: 4px; border-radius: 50%; background: var(--dgold); }
.pill { position: absolute; left: 196px; width: 720px; height: 140px; border-radius: 36px; background: #0B0B0B; }
.pill .n { position: absolute; left: 42px; top: 32px; font: 700 30px/1 var(--sans); color: var(--gold); letter-spacing: 0.08em; }
.pill .t { position: absolute; left: 122px; top: 18px; font: 600 66px/1 var(--serif); color: #fff; white-space: nowrap; }
.pill .s { position: absolute; left: 124px; top: 90px; font: 500 31px/1 var(--sans); color: rgba(255,255,255,0.62); white-space: nowrap; }

/* Proof */
.count { font-family: var(--serif); font-weight: 600; color: var(--gold); letter-spacing: -0.02em; }
.ticker { position: absolute; left: 0; right: 0; height: 60px; overflow: hidden; -webkit-mask-image: linear-gradient(90deg, transparent 0%, #000 18%, #000 82%, transparent 100%); mask-image: linear-gradient(90deg, transparent 0%, #000 18%, #000 82%, transparent 100%); }
.ticker .row { position: absolute; left: 0; top: 0; white-space: nowrap; font: 700 36px/60px var(--sans); letter-spacing: 0.14em; color: rgba(255,255,255,0.55); text-transform: uppercase; }
.ticker .row b { color: var(--gold); font-weight: 700; margin: 0 0.7em; }
.stars { position: absolute; left: 0; right: 0; display: flex; justify-content: center; gap: 18px; }
.stars svg { width: 64px; height: 64px; }

/* CTA */
.button { position: absolute; left: 50%; padding: 30px 56px 28px; border-radius: 100px; background: var(--gold); color: #0B0B0B; font: 700 38px/1 var(--sans); letter-spacing: 0.01em; white-space: nowrap; overflow: hidden; }
.button .ripple { position: absolute; width: 520px; height: 520px; margin: -260px 0 0 -260px; border-radius: 50%; background: rgba(255,255,255,0.55); }

