const D = window.DATA;
const { clamp, lerp, span, expoOut, easeIn, easeOut, easeInOut, spring, rand } = M;
const stage = document.getElementById("stage");
const FPS = D.fps;
const el = (tag, cls, parent = stage, text) => {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text != null) e.textContent = text;
  parent.appendChild(e);
  return e;
};
const set = (node, styles) => Object.assign(node.style, styles);
const f2 = (v) => v.toFixed(2);
const onFrame = (t) => Math.round(t * FPS) / FPS;

// The music: 120 BPM, a break from 1.0 s, the drop on 2.0 s, a bar every 2 s.
const SCENES = {
  hook: [0, 2.0],
  studio: [2.0, 4.0],
  phone: [4.0, 8.0],
  pillars: [8.0, 13.9],
  method: [13.85, 20.1],
  proof: [20.0, 24.0],
  cta: [24.0, 26.05],
  logo: [26.0, 30.1],
};

// A line of words that rise out of masks, one by one. parts: [[text, class], ...]
function riseLine(parent, parts, cls, top, size) {
  const line = el("div", `line ${cls}`, parent);
  set(line, { top: `${top}px`, fontSize: `${size}px` });
  const words = [];
  for (const [text, c] of parts) {
    for (const w of text.split(" ")) {
      if (words.length) line.appendChild(document.createTextNode(" "));
      const m = el("span", `m ${c ?? ""}`, line);
      words.push(el("span", "mi", m, w));
    }
  }
  return { line, words };
}
// starts: one time for the first word (then `stagger` apart), or one time per word.
function rise(words, t, starts, stagger = 0.06, dur = 0.8) {
  words.forEach((w, i) => {
    const a = Array.isArray(starts) ? starts[Math.min(i, starts.length - 1)] : starts + i * stagger;
    const p = expoOut(span(t, a, a + dur));
    w.style.transform = `translateY(${f2((1 - p) * 118)}%)`;
  });
}
function setSrc(img, url) {
  if (img.dataset.src !== url) {
    img.src = url;
    img.dataset.src = url;
  }
}
function makePhone(parent, w, h) {
  const p = el("div", "phone", parent);
  set(p, { width: `${w}px`, height: `${h}px` });
  el("div", "back", p);
  el("div", "body", p);
  const screen = el("div", "screen", p);
  const img = el("img", null, screen);
  el("div", "island", p);
  return { p, img };
}
function starSvg() {
  return `<svg viewBox="0 0 24 24"><path fill="#F6D43A" d="M12 1.8l3.1 6.6 7.2.9-5.3 5 1.4 7.1L12 17.9l-6.4 3.5 1.4-7.1-5.3-5 7.2-.9z"/></svg>`;
}

const S = {};
let grain;

window.init = async () => {
  await Promise.all([
    document.fonts.load('500 100px "Cormorant Garamond"'),
    document.fonts.load('italic 600 100px "Cormorant Garamond"'),
    document.fonts.load('600 100px "Cormorant Garamond"'),
    document.fonts.load('800 100px "Montserrat"'),
    document.fonts.load('600 30px "Montserrat"'),
    document.fonts.load('700 30px "Montserrat"'),
  ]);
  el("div", "bg");
  const scene = (name) => {
    const r = el("div", "scene");
    S[name] = { root: r };
    return r;
  };

  // 1. Hook: the brand's positioning, set like a title card, on the gold thread.
  {
    const r = scene("hook");
    const g = el("div", null, r);
    set(g, { position: "absolute", inset: "0", transformOrigin: "50% 48%" });
    const l1 = riseLine(g, [["Plus qu'une", "it"]], "", 690, 124);
    const l2 = riseLine(g, [["agence", ""]], "serif", 826, 190);
    const l3 = riseLine(g, [["marketing.", ""]], "serif", 1010, 190);
    const rule = el("div", "rule", g);
    set(rule, { left: "260px", width: "560px", top: "1236px" });
    const tag = el("div", "line label", g, "Magik Management · Montréal");
    set(tag, { top: "1290px", color: "rgba(255,255,255,0.62)" });
    Object.assign(S.hook, { g, l1, l2, l3, rule, tag });
  }

  // 2. The studio, on the drop.
  {
    const r = scene("studio");
    const plate = el("img", null, r);
    plate.src = M.image("studio");
    set(plate, { position: "absolute", left: "0", top: "0", width: "1080px", height: "1920px", transformOrigin: "50% 31%" });
    const shade = el("div", null, r);
    set(shade, { position: "absolute", inset: "0", background: "linear-gradient(to bottom, rgba(5,5,5,0.35) 0%, rgba(5,5,5,0) 22%, rgba(5,5,5,0) 48%, rgba(5,5,5,0.78) 70%, rgba(5,5,5,0.92) 100%)" });
    const l1 = riseLine(r, [["Where the", ""]], "serif", 1150, 124);
    const l2 = riseLine(r, [["Magik", "it"], ["happens.", ""]], "serif", 1272, 156);
    const black = el("div", null, r);
    set(black, { position: "absolute", inset: "0", background: "#050505", opacity: "0" });
    Object.assign(S.studio, { plate, l1, l2, black });
  }

  // 3. The mobile site, in a phone.
  {
    const r = scene("phone");
    set(r, { perspective: "1700px", perspectiveOrigin: "50% 42%" });
    const floor = el("div", "floor", r);
    set(floor, { top: "1270px", transform: "rotateX(82deg)" });
    const ground = el("div", "ground", r);
    set(ground, { left: "220px", top: "1600px", width: "640px", height: "96px" });
    const l1 = riseLine(r, [["De la visibilité", ""]], "serif", 236, 104);
    const l2 = riseLine(r, [["à la", ""], ["croissance.", "it"]], "serif", 346, 104);
    const ph = makePhone(r, 560, 1172);
    set(ph.p, { left: "260px", top: "468px" });
    Object.assign(S.phone, { floor, ground, l1, l2, ph });
  }

  // 4. Three pillars, flying out of depth, in front of the desktop site.
  {
    const r = scene("pillars");
    set(r, { perspective: "1800px", perspectiveOrigin: "50% 40%" });
    const br = el("div", "browser", r);
    set(br, { left: "40px", top: "880px", width: "1000px", height: "671px" });
    const bar = el("div", "bar", br);
    for (let i = 0; i < 3; i++) el("i", "dot", bar);
    el("div", "url", bar);
    const scr = el("div", "screen", br);
    const img = el("img", null, scr);
    const veil = el("div", null, r);
    set(veil, { position: "absolute", inset: "0", background: "linear-gradient(to bottom, rgba(7,7,7,1) 0%, rgba(7,7,7,0.9) 40%, rgba(7,7,7,0.25) 62%, rgba(7,7,7,0.6) 100%)" });
    const P = [
      { n: "01", fr: "Bâtir la marque", a: "Build the", b: "brand." },
      { n: "02", fr: "Créer la demande", a: "Create", b: "demand." },
      { n: "03", fr: "Accélérer la croissance", a: "Drive", b: "growth." },
    ].map((p, i) => {
      const g = el("div", null, r);
      set(g, { position: "absolute", inset: "0" });
      const idx = el("div", "line label", g);
      idx.innerHTML = `<span style="color:var(--gold)">${p.n}</span>&nbsp;&nbsp;—&nbsp;&nbsp;${p.fr}`;
      set(idx, { top: "448px", color: "rgba(255,255,255,0.72)" });
      const a = el("div", "line", g);
      set(a, { top: "520px", font: "800 128px/1 Montserrat", letterSpacing: "-0.035em" });
      const aw = p.a.split(" ").map((w, k) => {
        if (k) a.appendChild(document.createTextNode(" "));
        return el("span", "mi", a, w);
      });
      const b = el("div", "line it", g);
      set(b, { top: "642px", fontSize: "204px" });
      const bw = el("span", "mi", b, p.b);
      const rule = el("div", "rule", g);
      return { ...p, g, idx, aw, bw, rule, at: 8 + i * 2 };
    });
    Object.assign(S.pillars, { br, img, veil, P });
  }

  // 5. The method: the thread opens onto paper.
  {
    const r = scene("method");
    const paper = el("div", "paper", r);
    const c = el("div", null, r);
    set(c, { position: "absolute", inset: "0" });
    const label = el("div", "line left label", c, "Notre méthode");
    set(label, { top: "300px", color: "var(--dgold)" });
    const h1 = riseLine(c, [["Comment on", ""]], "left serif", 352, 136);
    const h2 = riseLine(c, [["travaille.", "it dark"]], "left serif", 486, 136);
    set(h1.line, { color: "#0B0B0B" });
    const STEPS = [
      ["01", "Stratégie", "On définit le cap."],
      ["02", "Production", "On crée le contenu."],
      ["03", "Post-production", "On le rend impeccable."],
      ["04", "Diffusion & résultats", "On le fait performer."],
    ];
    const top0 = 760;
    const gap = 172;
    const track = el("div", "track", c);
    set(track, { left: "131px", top: `${top0 + 70}px`, height: `${gap * 3}px` });
    const steps = STEPS.map(([n, t, s], i) => {
      const y = top0 + i * gap;
      const pill = el("div", "pill", c);
      set(pill, { top: `${y}px` });
      el("div", "n", pill, n);
      el("div", "t", pill, t);
      el("div", "s", pill, s);
      const node = el("div", "node", c);
      set(node, { left: "132px", top: `${y + 70}px` });
      el("i", null, node);
      return { pill, node, at: 14.5 + i };
    });
    Object.assign(S.method, { paper, c, label, h1, h2, track, steps });
  }

  // 6. Proof: 200+ brands, then the Google rating; client names run underneath.
  {
    const r = scene("proof");
    const A = el("div", null, r);
    set(A, { position: "absolute", inset: "0" });
    const la = el("div", "line label", A, "Ils nous font confiance");
    set(la, { top: "560px", color: "var(--gold)" });
    const ca = el("div", "line count", A);
    set(ca, { top: "612px", fontSize: "330px", lineHeight: "1" });
    const can = el("span", null, ca, "0");
    const plus = el("span", null, ca, "+");
    const sa = riseLine(A, [["marques accompagnées.", ""]], "serif", 1040, 84);
    set(sa.line, { fontStyle: "italic" });
    const B = el("div", null, r);
    set(B, { position: "absolute", inset: "0" });
    const lb = el("div", "line label", B, "Avis Google");
    set(lb, { top: "560px", color: "var(--gold)" });
    const cb = el("div", "line count", B, "4,9");
    set(cb, { top: "612px", fontSize: "330px" });
    const stars = el("div", "stars", B);
    set(stars, { top: "1050px" });
    const st = [0, 1, 2, 3, 4].map(() => {
      const s = el("span", null, stars);
      s.innerHTML = starSvg();
      return s;
    });
    const rule = el("div", "rule", r);
    set(rule, { top: "992px" });
    const ticker = el("div", "ticker", r);
    set(ticker, { top: "1222px" });
    const row = el("div", "row", ticker);
    const names = ["Scotiabank", "Century 21", "Sun Life", "iA Groupe financier", "Primerica", "GMF", "Glow Harmony", "Fade 2 Brooklyn", "Gala SDE", "Apollo"];
    row.innerHTML = [...names, ...names].map((n) => `<span>${n}</span>`).join("<b>·</b>");
    Object.assign(S.proof, { A, la, ca, can, plus, sa, B, lb, cb, st, rule, ticker, row });
  }

  // 7. The call to action.
  {
    const r = scene("cta");
    set(r, { perspective: "1700px", perspectiveOrigin: "50% 45%" });
    const l1 = riseLine(r, [["Parlons de", ""]], "serif", 232, 120);
    const l2 = riseLine(r, [["votre", ""], ["projet.", "it"]], "serif", 352, 120);
    const sub = el("div", "line label", r, "Réponse sous 48 h");
    set(sub, { top: "506px", color: "rgba(255,255,255,0.7)" });
    const ph = makePhone(r, 500, 1046);
    set(ph.p, { left: "290px", top: "596px" });
    const ground = el("div", "ground", r);
    set(ground, { left: "250px", top: "1596px", width: "580px", height: "86px" });
    const btn = el("div", "button", r, "Démarrer un projet  →");
    set(btn, { top: "1262px" });
    const ripple = el("i", "ripple", btn);
    Object.assign(S.cta, { l1, l2, ph, ground, btn, ripple, sub });
  }

  // 8. The logo, signed with the thread.
  {
    const r = scene("logo");
    const g = el("div", null, r);
    set(g, { position: "absolute", inset: "0", transformOrigin: "50% 48%" });
    const logo = el("img", null, g);
    logo.src = M.image("logo");
    set(logo, { position: "absolute", left: "120px", top: "800px", width: "840px", height: `${840 / 4.679}px` });
    const rule = el("div", "rule", g);
    set(rule, { left: "300px", width: "480px", top: "1043px", height: "3px" });
    const url = el("div", "line", g, "magikmanagement.com");
    set(url, { top: "1082px", font: "600 36px/1 Montserrat", color: "rgba(255,255,255,0.82)" });
    const cta = el("div", "line", g, "Démarrer un projet · Réponse sous 48 h");
    set(cta, { top: "1140px", font: "500 30px/1 Montserrat", color: "rgba(255,255,255,0.5)", letterSpacing: "0.04em" });
    Object.assign(S.logo, { g, logo, rule, url, cta });
  }

  // Film grain: one deterministic noise tile, moved every frame.
  grain = el("div", "grain");
  const cv = document.createElement("canvas");
  cv.width = cv.height = 256;
  const ctx = cv.getContext("2d");
  const im = ctx.createImageData(256, 256);
  for (let i = 0; i < 256 * 256; i++) {
    const v = Math.floor(rand(i * 1.37 + 3) * 255);
    im.data.set([v, v, v, 255], i * 4);
  }
  ctx.putImageData(im, 0, 0);
  set(grain, { backgroundImage: `url(${cv.toDataURL()})`, backgroundSize: "256px 256px" });
};

window.render = (t) => {
  const f = Math.round(t * FPS);
  grain.style.backgroundPosition = `${Math.floor(rand(f) * 256)}px ${Math.floor(rand(f + 77) * 256)}px`;
  for (const [name, [a, b]] of Object.entries(SCENES)) S[name].root.style.display = t >= a && t < b ? "block" : "none";

  // 1. Hook
  if (t < SCENES.hook[1]) {
    const h = S.hook;
    rise(h.l1.words, t, 0.0, 0.07);
    rise(h.l2.words, t, 0.32);
    rise(h.l3.words, t, 0.56);
    h.rule.style.transform = `scaleX(${f2(easeInOut(span(t, 0.8, 1.5)))})`;
    const tp = easeOut(span(t, 1.12, 1.6));
    set(h.tag, { opacity: f2(tp), letterSpacing: `${(0.5 - 0.18 * tp).toFixed(3)}em` });
    const out = easeIn(span(t, 1.74, 2.0));
    set(h.g, { transform: `scale(${(1 + 0.14 * out).toFixed(4)})`, opacity: f2(1 - out), filter: `blur(${f2(out * 12)}px)` });
  }

  // 2. Studio
  if (t >= SCENES.studio[0] && t < SCENES.studio[1]) {
    const s = S.studio;
    const settle = expoOut(span(t, 2.0, 2.9));
    const out = easeIn(span(t, 3.72, 4.0));
    const sc = 1.16 - 0.12 * settle - 0.02 * span(t, 2.9, 3.72) + 0.5 * out;
    s.plate.style.transform = `scale(${sc.toFixed(4)})`;
    rise(s.l1.words, t, [2.04, 2.14]);
    rise(s.l2.words, t, [2.5, 3.0]);
    const tf = 1 - easeIn(span(t, 3.66, 3.86));
    s.l1.line.style.opacity = s.l2.line.style.opacity = f2(tf);
    s.black.style.opacity = f2(out);
  }

  // 3. Phone
  if (t >= SCENES.phone[0] && t < SCENES.phone[1]) {
    const s = S.phone;
    const p = spring(t - 4.0, { stiffness: 80 });
    const d = easeInOut(span(t, 4.6, 8.0));
    const out = easeIn(span(t, 7.7, 8.0));
    const ty = (1 - p) * 1300 - 24 * d - 1500 * out;
    const rx = lerp(38, 8, p) - 3 * d + 24 * out;
    const ry = lerp(-34, -16, p) + 12 * d;
    const rz = lerp(8, 0, p);
    s.ph.p.style.transform = `translateY(${f2(ty)}px) rotateX(${f2(rx)}deg) rotateY(${f2(ry)}deg) rotateZ(${f2(rz)}deg)`;
    setSrc(s.ph.img, M.frame("mobile", 1.6 + Math.max(0, t - 4.3) * 1.05));
    s.ground.style.opacity = f2(clamp(p) * (1 - out));
    s.floor.style.opacity = f2(easeOut(span(t, 4.0, 4.8)) * (1 - out));
    s.floor.style.backgroundPosition = `0px ${f2((t - 4) * 40)}px`;
    rise(s.l1.words, t, 4.3, 0.06);
    rise(s.l2.words, t, [4.55, 4.62, 5.0]);
    const tf = 1 - easeIn(span(t, 7.62, 7.86));
    s.l1.line.style.opacity = s.l2.line.style.opacity = f2(tf);
  }

  // 4. Pillars
  if (t >= SCENES.pillars[0] && t < SCENES.pillars[1]) {
    const s = S.pillars;
    const p = spring(t - 8.0, { stiffness: 70 });
    const d = easeInOut(span(t, 8.0, 13.9));
    const out = easeIn(span(t, 13.5, 13.85));
    s.br.style.transform = `translateY(${f2((1 - p) * 700 + 140 * out)}px) translateZ(${f2(-120 - 300 * out)}px) rotateX(${f2(lerp(26, 9, p))}deg) rotateY(${f2(lerp(24, 13, p) - 8 * d)}deg)`;
    s.br.style.opacity = f2(clamp(p * 1.4) * (1 - out));
    setSrc(s.img, M.frame("desktop", 1.3 + (t - 8.0)));
    for (const q of s.P) {
      const on = t >= q.at - 0.01 && t < q.at + 2;
      q.g.style.display = on ? "block" : "none";
      if (!on) continue;
      const last = q.n === "03";
      const fly = last ? 0 : easeIn(span(t, q.at + 1.74, q.at + 2.0));
      const fade = last ? easeIn(span(t, 13.5, 13.75)) : 0;
      const ip = expoOut(span(t, q.at, q.at + 0.45));
      set(q.idx, { opacity: f2(ip * (1 - fly) * (1 - fade)), letterSpacing: `${(0.5 - 0.18 * ip).toFixed(3)}em` });
      q.aw.forEach((w, k) => {
        const e = expoOut(span(t, q.at + k * 0.08, q.at + 0.6 + k * 0.08));
        const z = -760 * (1 - e) + 520 * fly;
        set(w, { transform: `perspective(1400px) translateZ(${f2(z)}px)`, opacity: f2(clamp(e * 2) * (1 - fly) * (1 - fade)), filter: `blur(${f2((1 - e) * 10 + fly * 10)}px)` });
      });
      const e = expoOut(span(t, q.at + 0.5, q.at + 1.1));
      const z = -900 * (1 - e) + 620 * fly;
      set(q.bw, { transform: `perspective(1400px) translateZ(${f2(z)}px) translateY(${f2(-fade * 40)}px)`, opacity: f2(clamp(e * 2) * (1 - fly) * (1 - fade)), filter: `blur(${f2((1 - e) * 12 + fly * 10)}px)` });
      // The underline: draws under the word, and on the last pillar runs out to both edges.
      const width = 360;
      const y = 872;
      const draw = easeInOut(span(t, q.at + 0.85, q.at + 1.3)) * (1 - fly);
      const ext = last ? easeInOut(span(t, 13.45, 13.82)) : 0;
      const wpx = lerp(width, 1080, ext);
      set(q.rule, { left: `${f2(540 - wpx / 2)}px`, width: `${f2(wpx)}px`, top: `${y}px`, transform: `scaleX(${f2(Math.max(draw, ext))})`, opacity: f2(1 - fly) });
    }
  }

  // 5. Method
  if (t >= SCENES.method[0] && t < SCENES.method[1]) {
    const s = S.method;
    const open = expoOut(span(t, 13.85, 14.3));
    const close = easeIn(span(t, 19.78, 20.1));
    const sy = open * (1 - close);
    s.paper.style.transformOrigin = close > 0 ? "50% 993px" : "50% 873px";
    s.paper.style.transform = `scaleY(${sy.toFixed(4)})`;
    const cf = 1 - easeIn(span(t, 19.62, 19.8));
    set(s.c, { opacity: f2(cf), transform: `translateY(${f2(-18 * easeInOut(span(t, 18.0, 19.8)))}px)` });
    const lp = expoOut(span(t, 14.05, 14.5));
    set(s.label, { opacity: f2(lp), letterSpacing: `${(0.5 - 0.18 * lp).toFixed(3)}em` });
    rise(s.h1.words, t, 14.1, 0.07);
    rise(s.h2.words, t, 14.3);
    // The thread runs down from node to node as each step lands.
    const reach = s.steps.reduce((acc, st, i) => (i === 0 ? acc : acc + easeInOut(span(t, st.at - 0.4, st.at))), 0);
    s.track.style.transform = `scaleY(${f2(reach / 3)})`;
    s.steps.forEach((st, i) => {
      const e = expoOut(span(t, st.at, st.at + 0.55));
      set(st.pill, { opacity: f2(clamp(e * 1.6)), transform: `translateX(${f2((1 - e) * 90)}px) scale(${(0.96 + 0.04 * e).toFixed(4)})` });
      const n = spring(t - st.at + 0.05, { stiffness: 260 });
      st.node.style.transform = `scale(${f2(Math.max(0, n))})`;
    });
  }

  // 6. Proof
  if (t >= SCENES.proof[0] && t < SCENES.proof[1]) {
    const s = S.proof;
    const tq = onFrame(t);
    const swap = easeIn(span(t, 22.2, 22.45));
    const back = expoOut(span(t, 22.45, 23.0));
    const outAll = easeIn(span(t, 23.75, 24.0));
    // The rule arrives full width from the paper and settles under the number.
    const rw = lerp(1080, 520, expoOut(span(t, 20.0, 20.6)));
    set(s.rule, { left: `${f2(540 - rw / 2)}px`, width: `${f2(rw)}px`, opacity: f2(1 - outAll) });
    const ap = expoOut(span(t, 20.1, 20.6));
    set(s.la, { opacity: f2(ap), letterSpacing: `${(0.5 - 0.18 * ap).toFixed(3)}em` });
    s.can.textContent = String(Math.round(200 * easeOut(span(tq, 20.15, 21.3))));
    s.plus.style.opacity = f2(easeOut(span(t, 21.25, 21.5)));
    set(s.ca, { opacity: f2(clamp(ap * 2)), transform: `translateY(${f2((1 - ap) * 40)}px)` });
    rise(s.sa.words, t, 20.55, 0.06);
    set(s.A, { opacity: f2(1 - swap), transform: `translateY(${f2(-60 * swap)}px)`, display: swap >= 1 ? "none" : "block" });
    set(s.B, { opacity: f2(back * (1 - outAll)), transform: `translateY(${f2((1 - back) * 60)}px)`, display: t >= 22.45 ? "block" : "none" });
    s.cb.textContent = (Math.round(49 * easeOut(span(tq, 22.45, 23.1))) / 10).toFixed(1).replace(".", ",");
    s.st.forEach((st, i) => {
      const e = spring(t - (22.75 + i * 0.09), { stiffness: 300 });
      set(st, { display: "inline-block", transform: `scale(${f2(Math.max(0, e))})` });
    });
    const tk = expoOut(span(t, 20.4, 21.0));
    set(s.ticker, { opacity: f2(tk * (1 - outAll)) });
    s.row.style.transform = `translateX(${f2(-((t - 20) * 150) % (s.row.scrollWidth / 2))}px)`;
  }

  // 7. CTA
  if (t >= SCENES.cta[0] && t < SCENES.cta[1]) {
    const s = S.cta;
    const p = spring(t - 24.0, { stiffness: 85 });
    const out = easeIn(span(t, 25.78, 26.05));
    s.ph.p.style.transform = `translateX(${f2((1 - p) * 900 - 900 * out)}px) rotateY(${f2(lerp(52, -10, p) - 30 * out)}deg) rotateX(${f2(6)}deg)`;
    setSrc(s.ph.img, M.frame("mobile", 21.5 + Math.max(0, t - 24.0) * 0.18));
    s.ground.style.opacity = f2(clamp(p) * (1 - out));
    rise(s.l1.words, t, 24.05, 0.07);
    rise(s.l2.words, t, [24.3, 24.5]);
    const b = spring(t - 24.55, { stiffness: 200 });
    const press = span(t, 24.98, 25.08) * (1 - span(t, 25.08, 25.3));
    set(s.btn, { opacity: f2(clamp(b * 2) * (1 - out)), transform: `translateX(-50%) scale(${(lerp(0.6, 1, Math.max(0, b)) - 0.05 * press).toFixed(4)})` });
    const rp = span(t, 25.02, 25.55);
    set(s.ripple, { left: "64%", top: "50%", transform: `scale(${f2(easeOut(rp))})`, opacity: f2(rp > 0 && rp < 1 ? 0.55 * (1 - rp) : 0) });
    const sp = easeOut(span(t, 24.7, 25.15));
    set(s.sub, { opacity: f2(sp * (1 - out)), letterSpacing: `${(0.5 - 0.18 * sp).toFixed(3)}em` });
    s.l1.line.style.opacity = s.l2.line.style.opacity = f2(1 - out);
  }

  // 8. Logo
  if (t >= SCENES.logo[0]) {
    const s = S.logo;
    const r = expoOut(span(t, 26.1, 26.95));
    set(s.logo, { clipPath: `inset(0 ${f2((1 - r) * 100)}% 0 0)`, filter: `blur(${f2((1 - r) * 8)}px)`, transform: `translateY(${f2((1 - r) * 24)}px)` });
    s.rule.style.transform = `scaleX(${f2(easeInOut(span(t, 26.55, 27.25)))})`;
    const u = easeOut(span(t, 27.0, 27.6));
    set(s.url, { opacity: f2(u), letterSpacing: `${(0.4 - 0.18 * u).toFixed(3)}em` });
    s.cta.style.opacity = f2(easeOut(span(t, 27.35, 27.9)));
    s.g.style.transform = `scale(${(1 + 0.035 * span(t, 26.0, 30.0)).toFixed(4)})`;
  }
};
